import datetime,hashlib,json,os,stat,subprocess

def file_info(path):
    try:
        fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    except FileNotFoundError:
        return {"path":path,"state":"ABSENT"},None
    except OSError as e:
        return {"path":path,"state":"UNREADABLE","error":type(e).__name__+":"+str(e)},None
    try:
        s=os.fstat(fd); h=hashlib.sha256(); chunks=[]; total=0
        while True:
            b=os.read(fd,65536)
            if not b: break
            h.update(b); total+=len(b)
            if total<=4*1024*1024: chunks.append(b)
        info={"path":path,"state":"PRESENT","kind":"regular" if stat.S_ISREG(s.st_mode) else "other","uid":s.st_uid,"gid":s.st_gid,"mode":format(stat.S_IMODE(s.st_mode),"04o"),"size":s.st_size,"sha256":h.hexdigest()}
        return info,b"".join(chunks) if total<=4*1024*1024 else None
    finally: os.close(fd)

